package com.bank.dlq;

import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.header.internals.RecordHeader;
import org.apache.kafka.common.serialization.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
import java.util.logging.*;

public class DlqConsumerDemo {
    private static final Logger log = Logger.getLogger(DlqConsumerDemo.class.getName());
    private static final String SOURCE = "transfers";
    private static final String DLQ = "transfers.DLT";
    private static final int MAX_ATTEMPTS = 3;
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferProcessor processor = new TransferProcessor();

        Properties cp = new Properties();
        cp.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        cp.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        cp.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        cp.put(ConsumerConfig.GROUP_ID_CONFIG, "settlement-service");
        cp.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");
        cp.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");

        Properties pp = new Properties();
        pp.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        pp.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        pp.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        pp.put(ProducerConfig.ACKS_CONFIG, "all");
        pp.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");

        try (Consumer<String, String> consumer = new KafkaConsumer<>(cp);
             Producer<String, String> dlqProducer = new KafkaProducer<>(pp)) {

            consumer.subscribe(List.of(SOURCE));
            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
                for (ConsumerRecord<String, String> rec : records) {
                    handleRecord(processor, dlqProducer, rec);
                    // Commit AFTER the record is processed OR safely dead-lettered.
                    consumer.commitSync(Map.of(
                        new org.apache.kafka.common.TopicPartition(rec.topic(), rec.partition()),
                        new OffsetAndMetadata(rec.offset() + 1)));
                }
            }
        }
    }

    private static void handleRecord(TransferProcessor processor,
                                     Producer<String, String> dlqProducer,
                                     ConsumerRecord<String, String> rec) {
        int attempt = 0;
        while (true) {
            attempt++;
            try {
                processor.process(rec.key(), rec.value());
                log.info(() -> "Processed transfer " + rec.key() + " offset " + rec.offset());
                return;   // success → caller commits
            } catch (PermanentProcessingException permanent) {
                // Never retry a poison message: straight to the DLQ.
                routeToDlq(dlqProducer, rec, permanent, attempt);
                return;
            } catch (TransientProcessingException transient_) {
                if (attempt >= MAX_ATTEMPTS) {
                    log.warning(() -> "Retries exhausted for " + rec.key() + " → DLQ");
                    routeToDlq(dlqProducer, rec, transient_, attempt);
                    return;
                }
                long backoff = 200L * attempt;   // simple linear backoff
                log.warning(() -> "Transient failure for " + rec.key()
                        + " attempt " + (attempt) + "/" + MAX_ATTEMPTS + ", retrying");
                sleep(backoff);
            }
        }
    }

    private static void routeToDlq(Producer<String, String> dlqProducer,
                                   ConsumerRecord<String, String> rec,
                                   Exception cause, int attempts) {
        // Preserve original key+value; add failure metadata as headers for redrive.
        ProducerRecord<String, String> dlqRecord =
            new ProducerRecord<>(DLQ, rec.key(), rec.value());
        dlqRecord.headers()
            .add(h("x-original-topic", rec.topic()))
            .add(h("x-original-partition", String.valueOf(rec.partition())))
            .add(h("x-original-offset", String.valueOf(rec.offset())))
            .add(h("x-exception-class", cause.getClass().getSimpleName()))
            .add(h("x-exception-message", String.valueOf(cause.getMessage())))
            .add(h("x-attempts", String.valueOf(attempts)))
            .add(h("x-failed-at", String.valueOf(System.currentTimeMillis())));
        try {
            dlqProducer.send(dlqRecord).get();   // ensure DLQ write succeeds before commit
            log.severe(() -> "Dead-lettered " + rec.key() + " to " + DLQ
                    + " reason=" + cause.getClass().getSimpleName());
        } catch (Exception e) {
            // DLQ write failed → do NOT commit → record will be retried, not lost.
            throw new RuntimeException("Failed to write to DLQ; will retry record", e);
        }
    }

    private static RecordHeader h(String k, String v) {
        return new RecordHeader(k, v.getBytes(StandardCharsets.UTF_8));
    }

    private static void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
    }
}

