class TransferProcessor {
    // Throws PermanentProcessingException for poison messages, Transient for retryable.
    void process(String key, String json) {
        if (json == null || !json.startsWith("{"))
            throw new PermanentProcessingException("unparseable JSON");
        if (json.contains("\"amount\":-"))
            throw new PermanentProcessingException("negative amount not allowed");
        if (json.contains("\"simulateTimeout\":true"))
            throw new TransientProcessingException("downstream ledger timeout");
        // otherwise: apply the transfer to the ledger (omitted) — success
    }
}

// ─── Would be in exception/PermanentProcessingException.java ───
class PermanentProcessingException extends RuntimeException {
    PermanentProcessingException(String msg) { super(msg); }
}

// ─── Would be in exception/TransientProcessingException.java ───
class TransientProcessingException extends RuntimeException {
    TransientProcessingException(String msg) { super(msg); }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
